export type ResolvePageDetailInput = {
  params: PageDetailParams;
  sources: readonly DataSource<ContentRegistry, PageDetailExecutionContext>[];
  schedulingMode?: SchedulingMode;
  budget?: ResolutionBudgetOptions;
  observer?: ResolutionObserver;
  backingResources?: ReadonlyMap<ResourceKey, unknown>;
  signal?: AbortSignal;
};

export type ResolvePageDetailResult = {
  pageDetail: PageDetailResult;
  contentMap: ContentMap<ContentRegistry>;
  islands: IslandMap;
  islandDependencies: IslandDependencyMap;
  errors: readonly ResolutionError[];
  promotedResourceKeys: readonly ResourceKey[];
};

export async function resolvePageDetail(
  input: ResolvePageDetailInput,
): Promise<ResolvePageDetailResult> {
  const executionContext = {
    spaceId: input.params.spaceId,
    environmentId: input.params.environmentId,
    locale: input.params.locale,
  };
  const root = pageAri({ spaceId: input.params.spaceId, environmentId: input.params.environmentId, id: input.params.pageId, locale: input.params.locale });
  const resolver = createResourceGraphResolver<ContentRegistry, PageDetailExecutionContext>({
    sources: input.sources,
    strategy: createPageDetailStrategy(input.params).build(),
    schedulingMode: input.schedulingMode,
    budget: input.budget,
    observer: input.observer,
  });

  const {
    contentMap,
    islands,
    islandDependencies,
    errors,
    failures,
    promotedResourceKeys,
    redirects,
  } = await resolver.resolve({
    roots: [root],
    executionContext,
    backingResources: input.backingResources,
    signal: input.signal,
  });

  const pageDetail = projectPageDetail(root, contentMap, {
    params: input.params,
    redirects,
    failures,
  });

  return {
    pageDetail,
    contentMap,
    islands,
    islandDependencies,
    errors,
    promotedResourceKeys,
  };
}
